from pathlib import Path
c=Path('outputs/Stratus/shaders/core')
p=c/'optics-cube.glsl';s=p.read_text().replace('// Six camera-centred 90 degree views share one 4 by 2 atlas.','// Six surrounding views plus two raised views recover more refracted\n// surfaces hidden behind foreground block edges, within one 4 by 2 atlas.')
s=s.replace('vec3 cubeForward(int face){','vec3 cubeOrigin(int face){return face>=6?vec3(0,2.5,0):vec3(0);}\nfloat cubeExtent(int face){return face>=6?2.5:cubeScale;}\nvec3 cubeForward(int face){\n if(face==6)return mat3(gbufferModelViewInverse)*vec3(0,0,-1);\n if(face==7)return vec3(0,-1,0);')
s=s.replace('return face<2?vec3(0,0,1):vec3(1,0,0);','return face==6?mat3(gbufferModelViewInverse)*vec3(1,0,0):(face<2?vec3(0,0,1):vec3(1,0,0));').replace('*cubeScale)','*cubeExtent(face))');p.write_text(s)
p=c/'optics-cache.geom.glsl';s=p.read_text().replace('#include "/core/optics-cube.glsl"','#include "/core/frame.glsl"\n#include "/core/optics-cube.glsl"').replace('max_vertices=18','max_vertices=24').replace('face<6','face<8').replace('cubeCoordinates(vertexPoint[i],face)','cubeCoordinates(vertexPoint[i]-cubeOrigin(face),face)').replace('p.xy/=cubeScale','p.xy/=cubeExtent(face)');p.write_text(s)
p=c/'optics-cache.frag.glsl';s=p.read_text().replace('length(cachePoint));','length(cachePoint-cubeOrigin(cacheFace)));');p.write_text(s)
p=c/'scene-trace.glsl';s=p.read_text().replace('cubeCoordinates(pWorld,opticsFace)','cubeCoordinates(pWorld-cubeOrigin(opticsFace),opticsFace)').replace('max(q.z,0.00001)*cubeScale','max(q.z,0.00001)*cubeExtent(opticsFace)').replace('mat3(gbufferModelView)*normalize(cubeRay(uv,opticsFace))*radius','mat3(gbufferModelView)*(normalize(cubeRay(uv,opticsFace))*radius+cubeOrigin(opticsFace))').replace('cubeCoordinates(mat3(gbufferModelViewInverse)*start,opticsFace)','cubeCoordinates(mat3(gbufferModelViewInverse)*start-cubeOrigin(opticsFace),opticsFace)').replace('cubeCoordinates(mat3(gbufferModelViewInverse)*end,opticsFace)','cubeCoordinates(mat3(gbufferModelViewInverse)*end-cubeOrigin(opticsFace),opticsFace)').replace('p.xy/cubeScale','p.xy/cubeExtent(opticsFace)').replace('q.xy/cubeScale','q.xy/cubeExtent(opticsFace)').replace('face<6','face<8').replace('cubeCoordinates(worldOrigin,face)','cubeCoordinates(worldOrigin-cubeOrigin(face),face)').replace('o.z*cubeScale','o.z*cubeExtent(face)').replace('d.z*cubeScale','d.z*cubeExtent(face)');p.write_text(s)
